SELECT lgo.id,lgo.type,lgo.member_id,lgo.platform_id,lgo.money FROM log_game_order lgo
WHERE lgo.type = 1 AND ((lgo.status =10 AND lgo.retry_count > 3) OR (lgo.status = 1 AND TIMESTAMPDIFF(MINUTE,b_time,NOW()) > 10)) AND
NOT EXISTS (SELECT transfer_id FROM member_game_transfer WHERE transfer_id = lgo.id)


	and (member_id = #{searchValue} or user_name like concat(#{searchValue}, '%'))


	and lgo.type = #{type}


	and lgo.platform_id = #{platformId}


	and lgo.b_time >= #{startTime}


	and lgo.b_time <= #{endTime}

SELECT lgo.id,lgo.type,lgo.member_id,lgo.platform_id,lgo.money FROM log_game_order lgo
WHERE lgo.type = 2 AND lgo.status IN (5, 6, 8, 9, 10) AND lgo.id IN (
SELECT transfer_id FROM member_game_transfer WHERE transfer_id = lgo.id AND transfer_state = 'Succeeded' AND
transfer_type ='Withdraw')

	and (member_id = #{searchValue} or user_name like concat(#{searchValue}, '%'))


	and lgo.type = #{type}


	and lgo.platform_id = #{platformId}


	and lgo.b_time >= #{startTime}


	and lgo.b_time <= #{endTime}

SELECT lgo.id,lgo.type,lgo.member_id,lgo.platform_id,lgo.money FROM log_game_order lgo
WHERE 1 = 1 AND (
	(
		lgo.type = 1 AND lgo.status =10 AND lgo.retry_count > 3 AND
		NOT EXISTS (SELECT transfer_id FROM member_game_transfer WHERE transfer_id = lgo.id)
	)
	OR
	(
		lgo.type = 2 AND lgo.status IN (5, 6, 8, 9, 10) AND lgo.id IN (
		SELECT transfer_id FROM member_game_transfer WHERE transfer_id = lgo.id AND transfer_state = 'Succeeded' AND
		transfer_type ='Withdraw')
	)
)

	and (member_id = #{searchValue} or user_name like concat(#{searchValue}, '%'))


	and lgo.type = #{type}


	and lgo.platform_id = #{platformId}


	and lgo.b_time >= #{startTime}


	and lgo.b_time <= #{endTime}
